inspector = inspector.replace('w-[420px] shrink-0 flex-col border-l border-slate-200 bg-white 2xl:w-[460px]', 'w-[340px] shrink-0 flex-col border-l border-indigo-100 bg-white 2xl:w-[380px]');
inspector = inspector.replace('[["content","Nội dung"],["design","Thiết kế"],["media","Media"],["copilot","AI"],["sources","Nguồn"]]', '[["content","Nội dung"],["design","Thiết kế"],["media","Media"],["copilot","AI trợ lý"],["sources","Nguồn"]]');
inspector = inspector.replace('AI Copilot</div>', 'AI trợ lý</div>');
