const loginV2 = "\"use client\";\n\nimport { useState } from \"react\";\nimport { api, setSession } from \"@/lib/api\";\n\nexport default function LoginPage() {\n  const [mode,setMode]=useState<\"login\"|\"register\">(\"login\");\n  const [email,setEmail]=useState(\"\"); const [password,setPassword]=useState(\"\"); const [name,setName]=useState(\"\");\n  const [role,setRole]=useState<\"teacher\"|\"student\">(\"teacher\"); const [error,setError]=useState(\"\"); const [busy,setBusy]=useState(false);\n\n  async function submit() {\n    setBusy(true); setError(\"\");\n    try {\n      const r=mode===\"login\" ? await api.login(email,password) : await api.register(email,password,name,role);\n      setSession(r.access_token,r.user);\n      location.href = r.user.role === \"student\" ? \"/learn\" : r.user.role === \"admin\" ? \"/admin\" : \"/classrooms\";\n    } catch(e){ setError(e instanceof Error?e.message:\"Không thể đăng nhập\"); } finally { setBusy(false); }\n  }\n\n  return <main className=\"grid min-h-screen bg-[#f6f8fe] lg:grid-cols-[1.05fr_.95fr]\">\n    <section className=\"relative hidden overflow-hidden bg-gradient-to-br from-indigo-700 via-violet-600 to-indigo-500 p-12 text-white lg:flex lg:flex-col lg:justify-between\">\n      <div className=\"absolute -right-24 -top-24 h-80 w-80 rounded-full bg-white/10 blur-2xl\"/><div className=\"absolute bottom-20 left-16 h-52 w-52 rounded-full bg-cyan-300/15 blur-3xl\"/>\n      <button onClick={()=>location.href=\"/\"} className=\"relative flex w-fit items-center gap-3\"><span className=\"grid h-11 w-11 place-items-center rounded-2xl bg-white/15 text-xl backdrop-blur\">▰</span><span className=\"text-xl font-black\">AI E-Learning Studio</span></button>\n      <div className=\"relative max-w-xl\"><span className=\"inline-flex rounded-full border border-white/20 bg-white/10 px-3 py-1 text-[10px] font-black uppercase tracking-[.18em]\">Nền tảng bài giảng số V2</span><h1 className=\"mt-5 text-5xl font-black leading-[1.05]\">Tạo bài giảng thông minh.<br/>Dạy học dễ dàng hơn.</h1><p className=\"mt-5 max-w-lg text-base leading-7 text-indigo-100\">Từ tài liệu nguồn đến bài học tương tác, lớp học, giao bài, báo cáo và xuất SCORM trong một workspace thống nhất.</p>\n        <div className=\"mt-8 grid grid-cols-3 gap-3\">{[[\"✦\",\"AI Lesson Builder\"],[\"▣\",\"Editor trực quan\"],[\"▥\",\"Analytics\"]].map(([i,t])=><div key={t} className=\"rounded-2xl border border-white/15 bg-white/10 p-4 backdrop-blur\"><div className=\"text-2xl\">{i}</div><div className=\"mt-2 text-xs font-black\">{t}</div></div>)}</div>\n      </div>\n      <div className=\"relative text-xs text-indigo-100\">Giáo viên · Học sinh · Quản trị viên</div>\n    </section>\n\n    <section className=\"flex items-center justify-center p-5 md:p-10\">\n      <div className=\"w-full max-w-md\">\n        <button onClick={()=>location.href=\"/\"} className=\"mb-6 flex items-center gap-2 lg:hidden\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-indigo-600 text-white\">▰</span><span className=\"font-black text-indigo-800\">AI E-Learning Studio</span></button>\n        <div className=\"rounded-[28px] border border-indigo-100 bg-white p-6 shadow-2xl shadow-indigo-100/60 md:p-8\">\n          <div className=\"mb-6\"><div className=\"text-[11px] font-black uppercase tracking-[.18em] text-indigo-600\">{mode===\"login\"?\"Chào mừng trở lại\":\"Tạo tài khoản mới\"}</div><h2 className=\"mt-2 text-3xl font-black tracking-tight\">{mode===\"login\"?\"Đăng nhập\":\"Đăng ký\"}</h2><p className=\"mt-2 text-sm leading-6 text-slate-500\">{mode===\"login\"?\"Tiếp tục vào không gian dạy và học của bạn.\":\"Chọn vai trò phù hợp để bắt đầu sử dụng hệ thống.\"}</p></div>\n\n          {mode===\"register\"&&<div className=\"mb-4 grid grid-cols-2 gap-2\"><button onClick={()=>setRole(\"teacher\")} className={\"rounded-xl border px-3 py-3 text-sm font-black \"+(role===\"teacher\"?\"border-indigo-500 bg-indigo-50 text-indigo-700\":\"border-slate-200 text-slate-500\")}>👩‍🏫 Giáo viên</button><button onClick={()=>setRole(\"student\")} className={\"rounded-xl border px-3 py-3 text-sm font-black \"+(role===\"student\"?\"border-indigo-500 bg-indigo-50 text-indigo-700\":\"border-slate-200 text-slate-500\")}>🎓 Học sinh</button></div>}\n\n          <div className=\"space-y-3\">\n            {mode===\"register\"&&<label className=\"block\"><span className=\"mb-1.5 block text-xs font-black text-slate-600\">Họ và tên</span><input className=\"input\" placeholder=\"Nguyễn Văn A\" value={name} onChange={e=>setName(e.target.value)}/></label>}\n            <label className=\"block\"><span className=\"mb-1.5 block text-xs font-black text-slate-600\">Email</span><input className=\"input\" type=\"email\" placeholder=\"email@school.edu.vn\" value={email} onChange={e=>setEmail(e.target.value)}/></label>\n            <label className=\"block\"><span className=\"mb-1.5 block text-xs font-black text-slate-600\">Mật khẩu</span><input className=\"input\" type=\"password\" placeholder=\"Tối thiểu 8 ký tự\" value={password} onChange={e=>setPassword(e.target.value)}/></label>\n          </div>\n\n          {error&&<div className=\"mt-4 rounded-xl border border-rose-200 bg-rose-50 p-3 text-xs font-semibold text-rose-700\">{error}</div>}\n          <button disabled={busy||!email||!password||(mode===\"register\"&&!name)} onClick={submit} className=\"mt-5 w-full rounded-xl bg-gradient-to-r from-indigo-600 to-violet-600 px-4 py-3.5 text-sm font-black text-white shadow-lg shadow-indigo-100 disabled:opacity-40\">{busy?\"Đang xử lý…\":mode===\"login\"?\"Đăng nhập →\":\"Tạo tài khoản →\"}</button>\n\n          <div className=\"mt-4 flex items-center justify-between gap-3 text-xs\"><button onClick={()=>{setMode(mode===\"login\"?\"register\":\"login\");setError(\"\")}} className=\"font-bold text-slate-500 hover:text-indigo-700\">{mode===\"login\"?\"Chưa có tài khoản? Đăng ký\":\"Đã có tài khoản? Đăng nhập\"}</button>{mode===\"login\"&&<a href=\"/forgot-password\" className=\"font-black text-indigo-600\">Quên mật khẩu?</a>}</div>\n        </div>\n      </div>\n    </section>\n  </main>;\n}\n";
fs.writeFileSync(path.join(root, "frontend/app/login/page.tsx"), loginV2);

