fs.writeFileSync(path.join(root,"frontend/app/assistant/page.tsx"),"\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport { api } from \"@/lib/api\";\nimport type { AuthUser, Project } from \"@/lib/types\";\n\nfunction stateLabel(status?:string|null){\n  const s=String(status||\"\").toLowerCase();\n  if([\"complete\",\"ready\",\"publish\"].some(x=>s.includes(x)))return \"Sẵn sàng\";\n  if([\"draft\",\"plan\",\"generat\"].some(x=>s.includes(x)))return \"Đang soạn\";\n  return status||\"Đang xử lý\";\n}\n\nexport default function AssistantHub(){\n  const [user,setUser]=useState<AuthUser|null>(null);\n  const [projects,setProjects]=useState<Project[]>([]);\n  const [q,setQ]=useState(\"\");\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState(\"\");\n\n  useEffect(()=>{Promise.all([api.me(),api.listProjects()]).then(([me,items])=>{setUser(me);setProjects(items)}).catch((e)=>{if((e as any)?.status===401){location.href=\"/login\";return}setError(e.message)}).finally(()=>setLoading(false))},[]);\n  const rows=useMemo(()=>projects.filter(p=>!q.trim()||[p.title,p.subject,p.grade].filter(Boolean).join(\" \").toLowerCase().includes(q.trim().toLowerCase())),[projects,q]);\n\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\"><div className=\"flex h-[68px] items-center gap-4 px-4 md:px-7\"><button onClick={()=>location.href=\"/\"} className=\"flex items-center gap-2.5\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"hidden text-lg font-black text-indigo-800 sm:block\">AI E-Learning Studio</span></button><div className=\"hidden h-7 w-px bg-slate-200 lg:block\"/><span className=\"hidden text-sm font-semibold text-slate-500 lg:block\">AI trợ lý</span><div className=\"ml-auto flex items-center gap-2\"><span className=\"hidden text-xs font-bold text-slate-500 md:block\">{user?.display_name||user?.email}</span><button onClick={()=>location.href=\"/projects/new\"} className=\"rounded-xl bg-indigo-600 px-4 py-2.5 text-xs font-black text-white\">＋ Tạo bài mới</button></div></div></header>\n\n    <div className=\"mx-auto max-w-7xl p-4 md:p-8\">\n      <section className=\"relative overflow-hidden rounded-[30px] bg-gradient-to-br from-indigo-700 via-violet-600 to-indigo-500 p-6 text-white shadow-xl shadow-indigo-100 md:p-9\">\n        <div className=\"absolute -right-20 -top-20 h-72 w-72 rounded-full bg-white/10 blur-2xl\"/><div className=\"relative grid gap-6 lg:grid-cols-[1fr_280px] lg:items-center\"><div><span className=\"inline-flex rounded-full border border-white/20 bg-white/10 px-3 py-1 text-[10px] font-black uppercase tracking-[.18em]\">AI Teaching Copilot</span><h1 className=\"mt-4 text-3xl font-black md:text-4xl\">Trợ lý AI cho bài giảng của bạn</h1><p className=\"mt-3 max-w-2xl text-sm leading-6 text-indigo-100\">Chọn một bài giảng để vào Editor và dùng AI Copilot sửa nội dung, rút gọn, mở rộng, đề xuất hoạt động, thay visual prompt hoặc sinh lại một phần mà vẫn giữ dữ liệu giáo viên đã duyệt.</p><div className=\"mt-5 flex flex-wrap gap-2\"><button onClick={()=>location.href=\"/projects/new\"} className=\"rounded-xl bg-white px-5 py-3 text-xs font-black text-indigo-700\">Tạo bài với AI</button><button onClick={()=>location.href=\"/library\"} className=\"rounded-xl border border-white/25 bg-white/10 px-5 py-3 text-xs font-black\">Mở thư viện</button></div></div><div className=\"hidden lg:grid h-48 place-items-center rounded-[32px] border border-white/20 bg-white/10 backdrop-blur\"><div className=\"text-center\"><div className=\"text-7xl\">🤖</div><div className=\"mt-3 text-[10px] font-black uppercase tracking-[.2em] text-indigo-100\">Copilot ready</div></div></div></div>\n      </section>\n\n      <section className=\"mt-6 grid gap-4 md:grid-cols-3\">{[\n        [\"✎\",\"Chỉnh nội dung\",\"Rút gọn, mở rộng và cải thiện lời giảng ngay trên slide.\"],\n        [\"✦\",\"Đề xuất sư phạm\",\"Gợi ý câu hỏi, hoạt động học sinh và cấu trúc phần học.\"],\n        [\"▣\",\"Visual & Media\",\"Tối ưu visual prompt, hình ảnh và bố cục theo nội dung bài.\"],\n      ].map(([i,t,d])=><div key={t} className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm\"><div className=\"grid h-11 w-11 place-items-center rounded-xl bg-indigo-50 text-xl text-indigo-700\">{i}</div><div className=\"mt-3 text-sm font-black\">{t}</div><p className=\"mt-1 text-xs leading-5 text-slate-500\">{d}</p></div>)}</section>\n\n      <div className=\"mt-7 flex flex-col gap-3 md:flex-row md:items-end md:justify-between\"><div><h2 className=\"text-xl font-black\">Chọn bài giảng để làm việc với AI</h2><p className=\"mt-1 text-xs text-slate-400\">{projects.length} bài trong workspace</p></div><input value={q} onChange={e=>setQ(e.target.value)} className=\"input md:w-80\" placeholder=\"Tìm bài giảng…\"/></div>\n\n      {loading&&<div className=\"mt-4 rounded-2xl border bg-white p-10 text-center text-sm text-slate-400\">Đang tải workspace…</div>}\n      {error&&<div className=\"mt-4 rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700\">{error}</div>}\n      {!loading&&!error&&<div className=\"mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3\">{rows.map((p,i)=><article key={p.id} className=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg\">\n        <div className=\"flex items-start gap-3\"><div className={\"grid h-12 w-12 shrink-0 place-items-center rounded-xl text-xl \"+([\"bg-sky-50\",\"bg-violet-50\",\"bg-emerald-50\",\"bg-amber-50\"][i%4])}>{[\"🌍\",\"💻\",\"🌱\",\"📐\"][i%4]}</div><div className=\"min-w-0 flex-1\"><div className=\"line-clamp-2 text-sm font-black\">{p.title}</div><div className=\"mt-1 text-[10px] text-slate-400\">{[p.subject,p.grade?\"Lớp \"+p.grade:null,p.duration_minutes?p.duration_minutes+\" phút\":null].filter(Boolean).join(\" · \")||\"Bài giảng\"}</div></div><span className=\"rounded-lg bg-indigo-50 px-2 py-1 text-[9px] font-black text-indigo-700\">{stateLabel(p.status)}</span></div>\n        <div className=\"mt-5 grid grid-cols-2 gap-2\"><button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor?panel=ai\"} className=\"rounded-xl bg-indigo-600 px-3 py-2.5 text-xs font-black text-white\">✦ Mở AI Copilot</button><button onClick={()=>location.href=\"/projects/\"+p.id+\"/editor\"} className=\"rounded-xl border border-slate-200 px-3 py-2.5 text-xs font-black text-slate-600\">Mở Editor</button></div>\n      </article>)}</div>}\n      {!loading&&!error&&!rows.length&&<div className=\"mt-4 rounded-3xl border-2 border-dashed border-indigo-200 bg-white p-10 text-center text-sm text-slate-400\">Chưa có bài phù hợp. Hãy tạo một bài giảng để bắt đầu làm việc với AI.</div>}\n    </div>\n  </main>;\n}\n");

