fs.writeFileSync(path.join(root,"frontend/app/settings/page.tsx"),"\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { api, setSession } from \"@/lib/api\";\nimport type { AuthUser, Organization } from \"@/lib/types\";\n\nexport default function SettingsPage(){\n  const [user,setUser]=useState<AuthUser|null>(null);\n  const [orgs,setOrgs]=useState<Organization[]>([]);\n  const [error,setError]=useState(\"\");\n  useEffect(()=>{Promise.all([api.me(),api.listOrganizations()]).then(([u,o])=>{setUser(u);setOrgs(o)}).catch((e)=>{if((e as any)?.status===401){location.href=\"/login\";return}setError(e.message)})},[]);\n  async function logout(){try{await api.logout()}catch{}setSession(null,null);location.href=\"/login\"}\n  return <main className=\"min-h-screen bg-[#f6f8fe] text-slate-900\">\n    <header className=\"sticky top-0 z-40 border-b border-indigo-100 bg-white/95 backdrop-blur\"><div className=\"flex h-[68px] items-center gap-4 px-4 md:px-7\"><button onClick={()=>location.href=\"/\"} className=\"flex items-center gap-2.5\"><span className=\"grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-indigo-600 to-violet-500 text-white\">▰</span><span className=\"hidden text-lg font-black text-indigo-800 sm:block\">AI E-Learning Studio</span></button><div className=\"hidden h-7 w-px bg-slate-200 lg:block\"/><span className=\"hidden text-sm font-semibold text-slate-500 lg:block\">Cài đặt</span></div></header>\n    <div className=\"mx-auto max-w-5xl p-4 md:p-8\">\n      <div><div className=\"text-[11px] font-black uppercase tracking-[.18em] text-indigo-600\">Workspace Settings</div><h1 className=\"mt-1 text-3xl font-black\">Cài đặt</h1><p className=\"mt-1 text-sm text-slate-500\">Thông tin tài khoản, tổ chức và phiên đăng nhập hiện tại.</p></div>\n      {error&&<div className=\"mt-5 rounded-2xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700\">{error}</div>}\n      <div className=\"mt-6 grid gap-5 lg:grid-cols-[.8fr_1.2fr]\">\n        <section className=\"rounded-3xl border border-slate-200 bg-white p-6 shadow-sm\"><div className=\"grid h-16 w-16 place-items-center rounded-2xl bg-gradient-to-br from-indigo-600 to-violet-500 text-2xl font-black text-white\">{(user?.display_name||user?.email||\"U\").slice(0,1).toUpperCase()}</div><h2 className=\"mt-4 text-xl font-black\">{user?.display_name||\"Đang tải…\"}</h2><p className=\"mt-1 text-sm text-slate-500\">{user?.email||\"—\"}</p><div className=\"mt-4 inline-flex rounded-full bg-indigo-50 px-3 py-1 text-[10px] font-black uppercase text-indigo-700\">{user?.role||\"user\"}</div><button onClick={logout} className=\"mt-6 w-full rounded-xl border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-black text-rose-700\">Đăng xuất</button></section>\n        <section className=\"rounded-3xl border border-slate-200 bg-white p-6 shadow-sm\"><div className=\"flex items-center justify-between\"><div><h2 className=\"text-lg font-black\">Tổ chức / Trường học</h2><p className=\"mt-1 text-xs text-slate-400\">Các workspace mà tài khoản đang tham gia.</p></div><button onClick={()=>location.href=\"/organizations\"} className=\"rounded-xl bg-indigo-50 px-3 py-2 text-xs font-black text-indigo-700\">Quản lý</button></div><div className=\"mt-5 space-y-2\">{orgs.map(o=><button key={o.id} onClick={()=>location.href=\"/organizations\"} className=\"flex w-full items-center gap-3 rounded-xl border border-slate-100 p-3 text-left hover:border-indigo-200 hover:bg-indigo-50/30\"><span className=\"grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-lg\">🏫</span><span className=\"min-w-0 flex-1\"><span className=\"block truncate text-sm font-black\">{o.name}</span><span className=\"block text-[10px] text-slate-400\">{o.slug||\"Organization\"}</span></span><span className=\"text-indigo-500\">→</span></button>)}{!orgs.length&&<div className=\"rounded-xl border-2 border-dashed border-slate-200 p-6 text-center text-xs text-slate-400\">Chưa có tổ chức nào.</div>}</div></section>\n      </div>\n      <section className=\"mt-5 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm\"><h2 className=\"text-lg font-black\">AI E-Learning Studio V2</h2><div className=\"mt-4 grid gap-3 sm:grid-cols-3\">{[[\"Sinh bài\",\"Analyze → Plan → Generate\"],[\"Biên tập\",\"Editor + AI Copilot\"],[\"Phân phối\",\"Classroom · SCORM · HTML5\"]].map(([a,b])=><div key={a} className=\"rounded-xl bg-slate-50 p-4\"><div className=\"text-xs font-black text-indigo-700\">{a}</div><div className=\"mt-1 text-[11px] text-slate-500\">{b}</div></div>)}</div></section>\n    </div>\n  </main>;\n}\n");

